/**
 * How it works: numbered or icon steps in a row or a column. Axes: layout (row, column), marker (number, icon),
 * align, density, tone.
 */
import { type ReactNode } from "react";
import { IconBadge, Inline, List, ListItem, Stack, Text, Title } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { EmptyState } from "../components/empty-state";
import { SectionFrame } from "../components/section-frame";
import { cn } from "../utils";
import type { Step } from "./steps-list.types";

export type StepsListProps = {
  id: string;
  title: string;
  steps: Step[];
  empty?: string;
  layout?: "row" | "column";
  marker?: "number" | "icon";
  align?: "start" | "center";
  tone?: "default" | "muted";
  density?: "roomy" | "default" | "compact";
  landmarkLabel?: string;
};

export function StepsList({
  id,
  title,
  steps,
  empty = "",
  layout = "row",
  marker = "number",
  align = "start",
  tone = "default",
  density = "default",
  landmarkLabel,
}: StepsListProps) {
  return (
    <SectionFrame
      id={id}
      title={title}
      tone={tone}
      density={density}
      align={align}
      measure={(((layout as string) === "row") ? "default" : "2xl")}
      landmarkLabel={landmarkLabel}
    >
      {((steps?.length ?? 0) === 0) ? (
        <EmptyState icon="list-ordered" title={empty} />
      ) : (
        <List
          tag="ol"
          className={cn(
            "grid gap-6",
            (((layout as string) === "row") ? "sm:grid-cols-2 md:grid-cols-4" : "")
          )}
          data-slot="items"
        >
          {(steps ?? []).map((step, i) => (
            <ListItem key={step.id}
              className={cn(
                "flex gap-4",
                (((layout as string) === "row") ? "flex-col" : ""),
                (((align as string) === "center") ? "items-center text-center" : "")
              )}
              data-slot="item"
            >
              <IconBadge variant="primary" data-slot="marker">
                {((marker as string) === "icon") ? (
                  <LucideIcon name={step.icon} size={20} />
                ) : (
                  <Inline className="text-base font-bold">
                    {((i + 1) == null ? undefined : String((i + 1)))}
                  </Inline>
                )}
              </IconBadge>
              <Stack gap="2" align={(((align as string) === "center") ? "center" : "start")}>
                <Title as={3} size="xl" weight="bold">
                  {step.title}
                </Title>
                <Text size="sm" className="text-muted-foreground">
                  {step.text}
                </Text>
              </Stack>
            </ListItem>
          ))}
        </List>
      )}
    </SectionFrame>
  );
}

